// Controller layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Connects the workflow and domain to the page. No business logic here.
import { useMachine } from "@xstate/react";
import { dealsWorkflow } from "../workflow/deals.workflow.js";
import * as domain from "../domain/deals.domain.js";
import DealsPage from "../page/DealsPage.jsx";

export default function DealsController() {
  const [state, send] = useMachine(dealsWorkflow);
  const { items, selectedId, error } = state.context;

  return (
    <DealsPage
      status={String(state.value)}
      error={error}
      dealCount={domain.dealCount(items)}
      pipeline={domain.pipeline(items)}
      avgDeal={domain.avgDeal(items)}
      largest={domain.largest(items)}
      smallest={domain.smallest(items)}
      avgMargin={domain.avgMargin(items)}
      weighted={domain.weighted(items)}
      syncedAt={domain.syncedAt(items)}
      rows={domain.toDealRows(items)}
      selectedId={selectedId}
      formValues={domain.toFormValues(domain.findDeal(items, selectedId))}
      onEdit={(id) => send({ type: "EDIT", id })}
      onSave={(values) => send({ type: "SAVE", data: domain.toDealInput(values) })}
      onCancel={() => send({ type: "CANCEL" })}
    />
  );
}
